CREATE TABLE IF NOT EXISTS `apex-marketing-n8n.automated_article_creation.admin_commands` (
  idempotency_key STRING NOT NULL, action STRING NOT NULL, actor_email STRING NOT NULL,
  entity_id STRING NOT NULL, requested_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, payload JSON
);
ASSERT NOT EXISTS (SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.admin_commands` WHERE idempotency_key = @idempotency_key) AS 'This command was already processed.';
ASSERT (SELECT COUNT(*) FROM `apex-marketing-n8n.automated_article_creation.articles` WHERE article_id = @article_id AND campaign_id = @campaign_id AND doctor_id = @doctor_id AND status = @expected_status AND current_version = CAST(@expected_version AS INT64)) = 1 AS 'The article changed or is no longer waiting for doctor approval.';
BEGIN TRANSACTION;
UPDATE `apex-marketing-n8n.automated_article_creation.approvals` SET status = 'APPROVED', responded_at = CURRENT_TIMESTAMP(), response = @reason
WHERE article_id = @article_id AND approval_type = 'DOCTOR_REVIEW' AND status = 'PENDING';
UPDATE `apex-marketing-n8n.automated_article_creation.article_review_links` SET status = 'SUPERSEDED', responded_at = CURRENT_TIMESTAMP()
WHERE article_id = @article_id AND status IN ('READY', 'OPENED');
UPDATE `apex-marketing-n8n.automated_article_creation.articles` SET status = 'DOCTOR_APPROVED', doctor_approved_at = CURRENT_TIMESTAMP()
WHERE article_id = @article_id AND status = @expected_status AND current_version = CAST(@expected_version AS INT64);
UPDATE `apex-marketing-n8n.automated_article_creation.campaign_doctors` SET status = 'DOCTOR_APPROVED', updated_at = CURRENT_TIMESTAMP()
WHERE campaign_id = @campaign_id AND doctor_id = @doctor_id;
INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (GENERATE_UUID(), 'article', @article_id, 'doctor.approved_by_admin', CURRENT_TIMESTAMP(), 'admin_dashboard', NULL,
  TO_JSON(STRUCT(@actor_email AS actor_email, @reason AS evidence, CAST(@expected_version AS INT64) AS version_number, @idempotency_key AS idempotency_key)));
INSERT INTO `apex-marketing-n8n.automated_article_creation.admin_commands`
(idempotency_key, action, actor_email, entity_id, requested_at, completed_at, payload)
VALUES (@idempotency_key, 'approve_for_doctor', @actor_email, @article_id, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(),
  TO_JSON(STRUCT(@campaign_id AS campaign_id, @doctor_id AS doctor_id, @reason AS evidence, CAST(@expected_version AS INT64) AS version_number)));
COMMIT TRANSACTION;
SELECT TRUE AS ok, 'DOCTOR_APPROVED' AS status, @article_id AS article_id;

DECLARE v_send_at TIMESTAMP DEFAULT CASE
  WHEN @send_mode = 'scheduled' THEN TIMESTAMP(PARSE_DATETIME('%Y-%m-%dT%H:%M', @scheduled_send_local), @scheduled_send_timezone)
  WHEN @send_mode = 'in_10' THEN TIMESTAMP_ADD(CURRENT_TIMESTAMP(), INTERVAL 10 MINUTE)
  ELSE CURRENT_TIMESTAMP()
END;
DECLARE v_scheduled BOOL DEFAULT v_send_at > CURRENT_TIMESTAMP();

CREATE TABLE IF NOT EXISTS `apex-marketing-n8n.automated_article_creation.admin_commands` (
  idempotency_key STRING NOT NULL, action STRING NOT NULL, actor_email STRING NOT NULL,
  entity_id STRING NOT NULL, requested_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, payload JSON
);

ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_source_url STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_alt_text STRING; ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics` ADD COLUMN IF NOT EXISTS wordpress_publish_date DATE;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_source_type STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_rights_reference STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaigns`
  ADD COLUMN IF NOT EXISTS invitation_send_at TIMESTAMP;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaigns`
  ADD COLUMN IF NOT EXISTS preview_only BOOL;

ASSERT NOT EXISTS (
  SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.admin_commands`
  WHERE idempotency_key = @idempotency_key
) AS 'This command was already processed.';
ASSERT @audience IN ('Linked doctors', 'Presentation preview') AS 'Unsupported campaign audience.';
ASSERT @send_mode IN ('now', 'in_10', 'scheduled') AS 'Unsupported send mode.'; ASSERT ARRAY_LENGTH(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json))) BETWEEN 1 AND 200 AS 'Campaigns require 1-200 linked doctors.';
ASSERT v_send_at <= TIMESTAMP_ADD(CURRENT_TIMESTAMP(), INTERVAL 90 DAY) AS 'Scheduled send cannot be more than 90 days away.';
ASSERT @send_mode = 'now' OR v_send_at >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 MINUTE) AS 'Scheduled send time is already in the past.';

ASSERT NOT EXISTS (
  SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.campaigns`
  WHERE campaign_id = @campaign_id
) AS 'This campaign already exists.';

ASSERT ARRAY_LENGTH(JSON_QUERY_ARRAY(PARSE_JSON(@topics_json))) = 3 AS 'Exactly three topics are required.';
ASSERT NOT EXISTS (
  SELECT 1
  FROM UNNEST(JSON_QUERY_ARRAY(PARSE_JSON(@topics_json))) topic
  WHERE NOT STARTS_WITH(JSON_VALUE(topic, '$.featured_image_source_url'), 'https://apexparent.hostmanpowered.com/wp-content/uploads/')
    OR LENGTH(TRIM(JSON_VALUE(topic, '$.featured_image_alt_text'))) < 8 OR (NULLIF(TRIM(JSON_VALUE(topic, '$.wordpress_publish_date')), '') IS NOT NULL AND (SAFE_CAST(JSON_VALUE(topic, '$.wordpress_publish_date') AS DATE) IS NULL OR SAFE_CAST(JSON_VALUE(topic, '$.wordpress_publish_date') AS DATE) > CURRENT_DATE('America/Chicago')))


) AS 'Every topic needs a valid central image URL, alt text, and valid WordPress publish date.';

ASSERT (
  SELECT COUNT(*)
  FROM `apex-marketing-n8n.automated_article_creation.doctors` d
  JOIN `apex-marketing-n8n.automated_article_creation.practices` p USING (practice_id)
  WHERE d.doctor_id IN UNNEST(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json)))
    AND d.active = TRUE
    AND NULLIF(TRIM(d.email), '') IS NOT NULL
    AND (
      @audience = 'Presentation preview'
      OR (
        p.active = TRUE
        AND UPPER(COALESCE(p.publisher_type, '')) = 'WORDPRESS'
        AND NULLIF(TRIM(JSON_VALUE(SAFE.PARSE_JSON(p.publisher_config_reference), '$.wordpress_base_url')), '') IS NOT NULL
        AND NULLIF(TRIM(JSON_VALUE(SAFE.PARSE_JSON(p.publisher_config_reference), '$.credential_name')), '') IS NOT NULL
        AND (
          p.practice_id = 'practice_test_001'
          OR UPPER(COALESCE(JSON_VALUE(SAFE.PARSE_JSON(p.publisher_config_reference), '$.mapping_status'), '')) = 'VERIFIED'
        )
      )
    )
) = ARRAY_LENGTH(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json)))
AS 'Every selected doctor must be active and linked to a practice. Full article campaigns also require a verified publishing site.';

BEGIN TRANSACTION;

INSERT INTO `apex-marketing-n8n.automated_article_creation.campaigns`
(campaign_id, campaign_name, campaign_month, status, doctor_review_days, require_marketing_approval, created_at, launched_at, invitation_send_at, preview_only)
VALUES (
  @campaign_id,
  @campaign_name,
  DATE(@campaign_month),
  IF(v_scheduled, 'SCHEDULED', 'LAUNCHED'),
  5,
  IF(@audience = 'Presentation preview', FALSE, TRUE),
  CURRENT_TIMESTAMP(),
  IF(v_scheduled, NULL, CURRENT_TIMESTAMP()),
  v_send_at,
  @audience = 'Presentation preview'
);

INSERT INTO `apex-marketing-n8n.automated_article_creation.campaign_topics`
(topic_id, campaign_id, topic_title, topic_description, interview_guidance,
  featured_image_source_url, featured_image_alt_text, wordpress_publish_date,  
    topic_sort_order, active, created_at)
SELECT
  CONCAT(@campaign_id, '_topic_', CAST(offset + 1 AS STRING)),
  @campaign_id,
  JSON_VALUE(topic, '$.title'),
  JSON_VALUE(topic, '$.title'),
  NULL,
  JSON_VALUE(topic, '$.featured_image_source_url'),
  JSON_VALUE(topic, '$.featured_image_alt_text'), SAFE_CAST(JSON_VALUE(topic, '$.wordpress_publish_date') AS DATE),


  offset + 1,
  TRUE,
  CURRENT_TIMESTAMP()
FROM UNNEST(JSON_QUERY_ARRAY(PARSE_JSON(@topics_json))) topic WITH OFFSET;

INSERT INTO `apex-marketing-n8n.automated_article_creation.campaign_doctors`
(campaign_id, doctor_id, status, invited_at, created_at, updated_at)
SELECT @campaign_id, doctor_id, IF(v_scheduled, 'SCHEDULED', 'READY'), NULL, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()
FROM UNNEST(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json))) doctor_id;

INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (
  GENERATE_UUID(),
  'campaign',
  @campaign_id,
  IF(v_scheduled, 'campaign.scheduled_by_admin', 'campaign.started_by_admin'),
  CURRENT_TIMESTAMP(),
  'admin_dashboard',
  NULL,
  TO_JSON(STRUCT(
    @actor_email AS actor_email,
    (SELECT COUNT(DISTINCT practice_id) FROM `apex-marketing-n8n.automated_article_creation.doctors` WHERE doctor_id IN UNNEST(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json)))) AS practice_count,
    @audience AS audience,
    (@audience = 'Presentation preview') AS preview_only,
    @idempotency_key AS idempotency_key,
    v_send_at AS invitation_send_at,
    3 AS topic_count,
    ARRAY_LENGTH(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json))) AS recipient_count
  ))
);

INSERT INTO `apex-marketing-n8n.automated_article_creation.admin_commands`
(idempotency_key, action, actor_email, entity_id, requested_at, completed_at, payload)
VALUES (
  @idempotency_key,
  'launch_campaign',
  @actor_email,
  @campaign_id,
  CURRENT_TIMESTAMP(),
  CURRENT_TIMESTAMP(),
  TO_JSON(STRUCT(
    (SELECT COUNT(DISTINCT practice_id) FROM `apex-marketing-n8n.automated_article_creation.doctors` WHERE doctor_id IN UNNEST(JSON_VALUE_ARRAY(PARSE_JSON(@doctor_ids_json)))) AS practice_count,
    @audience AS audience,
    (@audience = 'Presentation preview') AS preview_only,
    @send_mode AS send_mode,
    v_send_at AS invitation_send_at,
    @topics_json AS topics_json,
    @doctor_ids_json AS doctor_ids_json
  ))
);

COMMIT TRANSACTION;

SELECT TRUE AS ok, IF(v_scheduled, 'SCHEDULED', 'LAUNCHED') AS status, @campaign_id AS campaign_id, v_send_at AS invitation_send_at;

ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaigns` ADD COLUMN IF NOT EXISTS interview_deadline DATE;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaigns` ADD COLUMN IF NOT EXISTS training_resource_url STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaigns` ADD COLUMN IF NOT EXISTS send_doctor_review_reminders BOOL;
ASSERT NULLIF(@interview_deadline, '') IS NULL OR SAFE_CAST(@interview_deadline AS DATE) IS NOT NULL AS 'The interview deadline must be a valid date.';
ASSERT NULLIF(@training_resource_url, '') IS NULL OR STARTS_WITH(@training_resource_url, 'https://') AS 'The training resource must use HTTPS.';
UPDATE `apex-marketing-n8n.automated_article_creation.campaigns`
SET interview_deadline = SAFE_CAST(NULLIF(@interview_deadline, '') AS DATE),
    training_resource_url = NULLIF(@training_resource_url, ''),
    send_doctor_review_reminders = LOWER(@send_doctor_review_reminders) != 'false'
WHERE campaign_id = @campaign_id;
SELECT TRUE AS ok, IF(v_scheduled, 'SCHEDULED', 'LAUNCHED') AS status, @campaign_id AS campaign_id, v_send_at AS invitation_send_at;

