ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaigns`
  ADD COLUMN IF NOT EXISTS archived_at TIMESTAMP;

CREATE TABLE IF NOT EXISTS `apex-marketing-n8n.automated_article_creation.admin_commands` (
  idempotency_key STRING NOT NULL, action STRING NOT NULL, actor_email STRING NOT NULL,
  entity_id STRING NOT NULL, requested_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, payload JSON
);

ASSERT NOT EXISTS (
  SELECT 1 FROM `apex-marketing-n8n.automated_article_creation.admin_commands`
  WHERE idempotency_key = @idempotency_key
) AS 'This command was already processed.';
ASSERT (SELECT COUNT(*) FROM `apex-marketing-n8n.automated_article_creation.campaigns` WHERE campaign_id = @campaign_id) = 1
  AS 'The campaign no longer exists.';
ASSERT (
  SELECT IF(
    LOWER(@archive) = 'true',
    COUNTIF(archived_at IS NULL) = 1,
    COUNTIF(archived_at IS NOT NULL) = 1
  )
  FROM `apex-marketing-n8n.automated_article_creation.campaigns`
  WHERE campaign_id = @campaign_id
) AS 'The campaign archive state changed. Refresh the dashboard before trying again.';

BEGIN TRANSACTION;
UPDATE `apex-marketing-n8n.automated_article_creation.campaigns`
SET archived_at = IF(LOWER(@archive) = 'true', CURRENT_TIMESTAMP(), NULL)
WHERE campaign_id = @campaign_id;

INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (
  GENERATE_UUID(), 'campaign', @campaign_id,
  IF(LOWER(@archive) = 'true', 'campaign.archived_by_admin', 'campaign.restored_by_admin'),
  CURRENT_TIMESTAMP(), 'admin_dashboard', NULL,
  TO_JSON(STRUCT(@actor_email AS actor_email, LOWER(@archive) = 'true' AS archived, @idempotency_key AS idempotency_key))
);

INSERT INTO `apex-marketing-n8n.automated_article_creation.admin_commands`
(idempotency_key, action, actor_email, entity_id, requested_at, completed_at, payload)
VALUES (
  @idempotency_key,
  IF(LOWER(@archive) = 'true', 'archive_campaign', 'restore_campaign'),
  @actor_email, @campaign_id, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(),
  TO_JSON(STRUCT(LOWER(@archive) = 'true' AS archived))
);
COMMIT TRANSACTION;
SELECT TRUE AS ok, IF(LOWER(@archive) = 'true', 'ARCHIVED', 'RESTORED') AS status, @campaign_id AS campaign_id;
